FROM patient_basic_info p
WHERE p.id IN (SELECT r.patient_id FROM patient_relation_doctor r
              WHERE r.doctor_id = #{doctorId} AND r.research_type IN ())

	AND (p.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE #{keywordEscape}
	     OR CAST(p.id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') ESCAPE #{keywordEscape}
	     OR p.study_no LIKE CONCAT('%', #{keyword}, '%') ESCAPE #{keywordEscape})

if.foreach:
AND (x.name LIKE CONCAT('%', #{word}, '%') ESCAPE #{keywordEscape}
     OR CAST(x.patientId AS CHAR) LIKE CONCAT('%', #{word}, '%') ESCAPE #{keywordEscape}
     OR x.studyNo LIKE CONCAT('%', #{word}, '%') ESCAPE #{keywordEscape}
     OR x.mobile LIKE CONCAT('%', #{word}, '%') ESCAPE #{keywordEscape})
